    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="v127_source_native_support",tickLimit=30)
    public void exactVanillaButtonSurvivesAgainstOfflineNativeBrickSupport(TestContext c){var world=c.getWorld();var root=c.getAbsolutePos(new BlockPos(3,8,3));UtilityV127GameTests.load(world,root,4);var block=CompositeArchitecture.kindBlock("source_bricks");var support=block.getDefaultState().with(CompositeRootBlock.VARIANT,2).with(CompositeRootBlock.ROTATION,2).with(ImportedCompactBlock.COMPACT,true);world.setBlockState(root.down(),support);var button=net.minecraft.block.Blocks.ACACIA_BUTTON.getDefaultState().with(net.minecraft.state.property.Properties.WALL_MOUNT_LOCATION,net.minecraft.block.enums.WallMountLocation.FLOOR).with(net.minecraft.state.property.Properties.HORIZONTAL_FACING,net.minecraft.util.math.Direction.EAST);c.assertTrue(world.getBlockEntity(root.down())==null&&support.isSideSolidFullSquare(world,root.down(),net.minecraft.util.math.Direction.UP)&&button.canPlaceAt(world,root),"Exact source button has an already installed native full-cube UP support before deferred owner phase");world.setBlockState(root,button);world.updateNeighbors(root.down(),support.getBlock());c.waitAndRun(2,()->{c.assertTrue(world.getBlockState(root).equals(button),"Vanilla floor button remains after real neighbor update");world.setBlockState(root,net.minecraft.block.Blocks.AIR.getDefaultState());world.setBlockState(root.down(),net.minecraft.block.Blocks.AIR.getDefaultState());c.complete();});}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="v127_worldedit",tickLimit=120)
    public void numericWholeObjectDeleteUndoCopyAndCompact(TestContext c) {
        if(!FabricLoader.getInstance().isModLoaded("worldedit")){System.out.println("V127 WorldEdit native integration: NOT_RUN (optional worldedit mod absent)");c.complete();return;}
        try{WithWorldEdit.run(c);}catch(Exception e){throw new IllegalStateException("Native WorldEdit integration failed",e);}
    }
